/**
 * Disclaimer: modules in _shims aren't intended to be imported by SDK users.
 */
import { manual } from './manual-types';
import * as REDACTED from "./REDACTED/types";
import { type RequestOptions } from '../core';

type SelectType<Manual, Auto> = unknown extends Manual ? Auto : Manual;

export const kind: string;

// @ts-ignore
export type Agent = SelectType<manual.Agent, REDACTED.Agent>;

// @ts-ignore
export const fetch: SelectType<typeof manual.fetch, typeof REDACTED.fetch>;

// @ts-ignore
export type Request = SelectType<manual.Request, REDACTED.Request>;
// @ts-ignore
export type RequestInfo = SelectType<manual.RequestInfo, REDACTED.RequestInfo>;
// @ts-ignore
export type RequestInit = SelectType<manual.RequestInit, REDACTED.RequestInit>;

// @ts-ignore
export type Response = SelectType<manual.Response, REDACTED.Response>;
// @ts-ignore
export type ResponseInit = SelectType<manual.ResponseInit, REDACTED.ResponseInit>;
// @ts-ignore
export type ResponseType = SelectType<manual.ResponseType, REDACTED.ResponseType>;
// @ts-ignore
export type BodyInit = SelectType<manual.BodyInit, REDACTED.BodyInit>;
// @ts-ignore
export type Headers = SelectType<manual.Headers, REDACTED.Headers>;
// @ts-ignore
export const Headers: SelectType<typeof manual.Headers, typeof REDACTED.Headers>;
// @ts-ignore
export type HeadersInit = SelectType<manual.HeadersInit, REDACTED.HeadersInit>;

// @ts-ignore
export type BlobPropertyBag = SelectType<manual.BlobPropertyBag, REDACTED.BlobPropertyBag>;
// @ts-ignore
export type FilePropertyBag = SelectType<manual.FilePropertyBag, REDACTED.FilePropertyBag>;
// @ts-ignore
export type FileFromPathOptions = SelectType<manual.FileFromPathOptions, REDACTED.FileFromPathOptions>;
// @ts-ignore
export type FormData = SelectType<manual.FormData, REDACTED.FormData>;
// @ts-ignore
export const FormData: SelectType<typeof manual.FormData, typeof REDACTED.FormData>;
// @ts-ignore
export type File = SelectType<manual.File, REDACTED.File>;
// @ts-ignore
export const File: SelectType<typeof manual.File, typeof REDACTED.File>;
// @ts-ignore
export type Blob = SelectType<manual.Blob, REDACTED.Blob>;
// @ts-ignore
export const Blob: SelectType<typeof manual.Blob, typeof REDACTED.Blob>;

// @ts-ignore
export type Readable = SelectType<manual.Readable, REDACTED.Readable>;
// @ts-ignore
export type FsReadStream = SelectType<manual.FsReadStream, REDACTED.FsReadStream>;
// @ts-ignore
export type ReadableStream = SelectType<manual.ReadableStream, REDACTED.ReadableStream>;
// @ts-ignore
export const ReadableStream: SelectType<typeof manual.ReadableStream, typeof REDACTED.ReadableStream>;

export function getMultipartRequestOptions<T = Record<string, unknown>>(
  form: FormData,
  opts: RequestOptions<T>,
): Promise<RequestOptions<T>>;

export function getDefaultAgent(url: string): any;

// @ts-ignore
export type FileFromPathOptions = SelectType<manual.FileFromPathOptions, REDACTED.FileFromPathOptions>;

export function fileFromPath(path: string, options?: FileFromPathOptions): Promise<File>;
export function fileFromPath(path: string, filename?: string, options?: FileFromPathOptions): Promise<File>;

export function isFsReadStream(value: any): value is FsReadStream;

export const init: () => void;
